CREATE TABLE `basketball_match` (`Team_ID` DECIMAL(18,2), `School_ID` DECIMAL(18,2), `Team_Name` VARCHAR(100), `ACC_Regular_Season` VARCHAR(100), `ACC_Percent` VARCHAR(100), `ACC_Home` VARCHAR(100), `ACC_Road` VARCHAR(100), `All_Games` VARCHAR(100), `All_Games_Percent` DECIMAL(18,2), `All_Home` VARCHAR(100), `All_Road` VARCHAR(100), `All_Neutral` VARCHAR(100));
CREATE TABLE `university` (`School_ID` DECIMAL(18,2), `School` VARCHAR(100), `Location` VARCHAR(100), `Founded` DECIMAL(18,2), `Affiliation` VARCHAR(100), `Enrollment` DECIMAL(18,2), `Nickname` VARCHAR(100), `Primary_conference` VARCHAR(100));
